import json, os, time
for name in ['1.3B-100B-RetNet-hybrid-12-1', '1.3B-100B-RetNet-hybrid-24-1']:
    f = f'/root/entrainment_gated_ft/lm_eval_clean/{name}.json'
    if os.path.exists(f):
        age = time.time() - os.path.getmtime(f)
        with open(f) as fh: data = json.load(fh)
        r = data.get('results', {})
        n = len([k for k in r if not k.startswith('mmlu_') or k == 'mmlu'])
        print(f'{name}: {n} top tasks, age={age:.0f}s')
        if n > 2:
            for t in sorted(r.keys()):
                if isinstance(r[t], dict) and not t.startswith('mmlu_'):
                    keys = [k for k in sorted(r[t]) if 'stderr' not in k and isinstance(r[t][k], (int,float))]
                    vals = ', '.join(f'{k}={r[t][k]:.4f}' for k in keys[:6])
                    print(f'  {t}: {vals}')
    else: print(f'{name}: no JSON')
"
